/**
* Converts a file (image/photo) into a base64 string and sends to Gemini API backend
*/
async function scanReceiptWithAI(file) {
	const base64 = await fileToBase64(file);
	const endpoint = `${typeof window !== "undefined" && (window.location.origin.includes("localhost") || window.location.protocol === "capacitor:") ? "https://ais-pre-3wiiypdjeboooeth4s5qlf-202698123569.us-east1.run.app" : ""}/api/gemini/parse-receipt`;
	const res = await fetch(endpoint, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			imageBase64: base64,
			mimeType: file.type || "image/jpeg"
		})
	});
	if (!res.ok) {
		const errorData = await res.json().catch(() => ({}));
		throw new Error(errorData.error || `Erro ${res.status}: Não foi possível ler a nota fiscal.`);
	}
	const data = await res.json();
	const amount = typeof data.amount === "number" ? data.amount : parseFloat(data.amount) || 0;
	return {
		title: (data.title || "Compra Nota Fiscal").trim(),
		amount,
		date: data.date && /^\d{4}-\d{2}-\d{2}$/.test(data.date) ? data.date : (/* @__PURE__ */ new Date()).toISOString().split("T")[0],
		category: [
			"moradia",
			"alimentacao",
			"transporte",
			"saude",
			"educacao",
			"lazer",
			"outros",
			"salario",
			"investimentos",
			"freelance"
		].includes(data.category) ? data.category : "alimentacao",
		paymentMethod: [
			"pix",
			"cartao_credito",
			"cartao_debito",
			"dinheiro",
			"transferencia"
		].includes(data.paymentMethod) ? data.paymentMethod : "cartao_credito",
		notes: data.notes || ""
	};
}
function fileToBase64(file) {
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.readAsDataURL(file);
		reader.onload = () => {
			const result = reader.result;
			resolve(result);
		};
		reader.onerror = (error) => reject(error);
	});
}
